<?php
require 'auth.php';
require 'config.php';
require_role('owner');

$summary = $conn->query('SELECT COUNT(*) AS orders_count, COALESCE(SUM(total), 0) AS revenue FROM orders WHERE status = "completed"')->fetch_assoc();
$productCount = $conn->query('SELECT COUNT(*) AS total FROM products')->fetch_assoc()['total'];
$orders = $conn->query('SELECT o.*, u.username AS cashier_name FROM orders o LEFT JOIN users u ON u.id = o.cashier_id ORDER BY o.created_at DESC LIMIT 100')->fetch_all(MYSQLI_ASSOC);
$products = $conn->query('SELECT p.*, c.name AS category_name FROM products p JOIN categories c ON c.id = p.category_id ORDER BY p.created_at DESC')->fetch_all(MYSQLI_ASSOC);
$categories = $conn->query('SELECT id, name FROM categories ORDER BY sort_order')->fetch_all(MYSQLI_ASSOC);
layout_start('Dashboard owner', 'owner');
?>
<section class="page-section"><div class="container"><div class="dashboard-heading"><div><span class="eyebrow">RUANG KENDALI</span><h1>Dashboard <em>owner.</em></h1></div><a class="btn btn-outline-dark rounded-pill px-4" href="export.php">↓ Unduh Excel</a></div><?php show_flash(); ?><div class="stats-grid"><div class="stat-card"><span>Total penjualan</span><strong><?= money($summary['revenue']) ?></strong><small>Pesanan selesai</small></div><div class="stat-card"><span>Pesanan selesai</span><strong><?= (int) $summary['orders_count'] ?></strong><small>Sepanjang waktu</small></div><div class="stat-card"><span>Produk aktif</span><strong><?= (int) $productCount ?></strong><small>Di katalog Kopipiro</small></div></div><div class="dashboard-panel"><div class="panel-heading"><div><span class="eyebrow">PERFORMA</span><h2>Penjualan 7 hari terakhir</h2></div></div><canvas id="salesChart" height="100"></canvas></div><div class="dashboard-panel"><div class="panel-heading"><div><span class="eyebrow">KATALOG</span><h2>Tambah produk</h2></div></div><form class="product-form" method="post" action="product-save.php" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="create"><div><label class="form-label">Nama produk</label><input class="form-control" name="name" required></div><div><label class="form-label">Kategori</label><select class="form-select" name="category_id" required><?php foreach ($categories as $item): ?><option value="<?= (int) $item['id'] ?>"><?= e($item['name']) ?></option><?php endforeach; ?></select></div><div><label class="form-label">Harga (Rp)</label><input class="form-control" type="number" min="0" name="price" required></div><div><label class="form-label">Gambar</label><input class="form-control" type="file" name="image" accept="image/jpeg,image/png,image/webp"></div><div class="form-wide"><label class="form-label">Deskripsi</label><textarea class="form-control" name="description" rows="2" required></textarea></div><label class="form-check form-wide"><input class="form-check-input" type="checkbox" name="is_featured" value="1"><span class="form-check-label">Tampilkan sebagai pilihan kami</span></label><button class="btn btn-dark rounded-pill px-4">Tambah produk</button></form></div><div class="dashboard-panel"><div class="panel-heading"><div><span class="eyebrow">PRODUK KOPIPIRO</span><h2>Kelola katalog</h2></div></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Produk</th><th>Kategori</th><th>Harga</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($products as $product): ?><tr><td><?= e($product['name']) ?></td><td><?= e($product['category_name']) ?></td><td><?= money($product['price']) ?></td><td><?= $product['is_available'] ? 'Tersedia' : 'Nonaktif' ?></td><td><form method="post" action="product-save.php"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= (int) $product['id'] ?>"><button class="btn btn-sm btn-outline-dark rounded-pill"><?= $product['is_available'] ? 'Nonaktifkan' : 'Aktifkan' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div></div><div class="dashboard-panel"><div class="panel-heading"><div><span class="eyebrow">SEMUA TRANSAKSI</span><h2>Pesanan terbaru</h2></div></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>No.</th><th>Pelanggan</th><th>Kasir</th><th>Total</th><th>Status</th><th>Waktu</th></tr></thead><tbody><?php foreach ($orders as $order): ?><tr><td>#<?= (int) $order['id'] ?></td><td><?= e($order['customer_name']) ?></td><td><?= e($order['cashier_name'] ?: 'Belum ditangani') ?></td><td><?= money($order['total']) ?></td><td><span class="status-pill status-<?= e($order['status']) ?>"><?= e($order['status']) ?></span></td><td><?= e(date('d M, H:i', strtotime($order['created_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></section><script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>fetch('sales-data.php').then(response => response.json()).then(data => new Chart(document.getElementById('salesChart'), {type: 'line', data: {labels: data.labels, datasets: [{data: data.values, borderColor: '#a35d37', backgroundColor: 'rgba(163,93,55,.12)', fill: true, tension: .35, pointRadius: 4}]}, options: {plugins: {legend: {display: false}}, scales: {y: {beginAtZero: true, ticks: {callback: value => 'Rp ' + new Intl.NumberFormat('id-ID').format(value)}}}}}));</script>
<?php layout_end(); ?>
